// The Worker posts {generatedAt, counters, totals}. Counter dimensions are
// positional: date | event | route | country | deviceClass | referrerHost |
// campaign, with the unique-visitor row carrying only date and the literal.
//
// Nothing here identifies a person. There is no field that could: the Worker
// discards the IP inside the request that resolved the country, and the Tier 1
// session id is never stored as a dimension.
const body = $input.first().json;
const counters = body.counters ?? [];
const yesterday = new Date(Date.parse(body.generatedAt) - 86400000)
  .toISOString()
  .slice(0, 10);

const onDay = counters.filter((row) => row.dimensions?.[0] === yesterday);
const sum = (event) =>
  onDay
    .filter((row) => row.dimensions?.[1] === event)
    .reduce((total, row) => total + (row.count ?? 0), 0);

const campaigns = new Map();
for (const row of onDay) {
  const campaign = row.dimensions?.[6];
  if (!campaign || campaign === '-') continue;
  const current = campaigns.get(campaign) ?? {views: 0, cv: 0};
  if (row.dimensions[1] === 'route_view') current.views += row.count ?? 0;
  if (row.dimensions[1] === 'cv_opened') current.cv += row.count ?? 0;
  campaigns.set(campaign, current);
}

const ranked = [...campaigns.entries()].sort((a, b) => b[1].views - a[1].views);
const views = sum('route_view');
const unique = sum('unique_visitor');
const cvOpens = sum('cv_opened');

// A quiet day sends nothing. A daily email that says "0" every day trains its
// only reader to ignore it, and this one exists to be noticed when it matters.
if (views === 0 && cvOpens === 0) {
  return [];
}

const lines = [
  `${views} views from ${unique} visitors.`,
  `${cvOpens} CV ${cvOpens === 1 ? 'open' : 'opens'}.`,
  '',
  ...ranked.map(([name, c]) => `${name}: ${c.views} views, ${c.cv} CV`),
];

return [
  {
    json: {
      date: yesterday,
      subject: `NOCTURNE ${yesterday}: ${views} views, ${cvOpens} CV`,
      text: lines.join('\n'),
    },
  },
];
